/** Parse one CSV line (handles quoted fields for PT-BR data). */
function parseCSVLine(line) {
  const out = [];
  let i = 0;
  while (i < line.length) {
    if (line[i] === '"') {
      i++;
      let s = '';
      while (i < line.length && line[i] !== '"') {
        s += line[i];
        if (line[i] === '"' && line[i + 1] === '"') { s += '"'; i += 2; continue; }
        i++;
      }
      if (line[i] === '"') i++;
      out.push(s.trim());
      if (line[i] === ',') i++;
    } else {
      let s = '';
      while (i < line.length && line[i] !== ',') s += line[i++];
      out.push(s.trim());
      if (line[i] === ',') i++;
    }
  }
  return out;
}

/** Parse CSV text (first line = header). Encoding should already be applied by FileReader. */
function parseCSV(text) {
  const lines = text.split(/\r?\n/).filter(l => l.length > 0);
  if (lines.length < 2) return [];
  const header = parseCSVLine(lines[0]);
  const rows = [];
  for (let i = 1; i < lines.length; i++) {
    const cells = parseCSVLine(lines[i]);
    const row = {};
    header.forEach((h, j) => { row[h] = (cells[j] || '').trim(); });
    rows.push(row);
  }
  return rows;
}

/** Read file as text with encoding (ISO-8859-1 for PT-BR CSVs). */
function readFileAsText(file, encoding) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result);
    reader.onerror = () => reject(reader.error);
    reader.readAsText(file, encoding || 'ISO-8859-1');
  });
}

function getSiteListSaveDir() {
  const configured = (document.getElementById('site-list-folder-path') && document.getElementById('site-list-folder-path').value || '').trim();
  // Ignore old UI summary text from previous versions.
  if (configured && !/files selected\s*\(/i.test(configured)) return configured;
  return 'C:/Downloader/cellref';
}

function dirnamePath(p) {
  const s = String(p || '').replace(/\\/g, '/');
  const i = s.lastIndexOf('/');
  return i > 0 ? s.slice(0, i) : '';
}

function commonPath(paths) {
  if (!paths.length) return '';
  const split = paths.map(p => p.replace(/\\/g, '/').split('/').filter(Boolean));
  const minLen = Math.min(...split.map(a => a.length));
  const out = [];
  for (let i = 0; i < minLen; i++) {
    const token = split[0][i];
    if (split.every(a => a[i].toLowerCase() === token.toLowerCase())) out.push(token);
    else break;
  }
  if (!out.length) return '';
  const first = paths[0].replace(/\\/g, '/');
  const hasDrive = /^[A-Za-z]:\//.test(first);
  return (hasDrive ? '' : '/') + out.join('/');
}

function inferBaseDirFromSelectedFiles(fileList) {
  const files = Array.from(fileList || []);
  if (!files.length) return '';
  // Works in environments that expose file.path (Electron/desktop shells).
  const fullDirs = files
    .map(f => dirnamePath(f.path || ''))
    .filter(Boolean);
  if (fullDirs.length) {
    const cp = commonPath(fullDirs);
    return cp || fullDirs[0];
  }
  return '';
}

async function saveSiteListToServer(rows) {
  const saveDir = getSiteListSaveDir();
  const response = await fetch('http://127.0.0.1:8765/api/save-site-list', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ rows, save_dir: saveDir })
  });
  if (!response.ok) {
    const errText = await response.text();
    throw new Error(errText || `Could not save site list (${response.status}).`);
  }
  return response.json();
}

async function tryAutoLoadSiteListFromBaseDir(silentIfMissing = true) {
  const baseDir = getSiteListSaveDir();
  if (!baseDir) return false;
  try {
    const response = await fetch('http://127.0.0.1:8765/api/load-site-list', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ base_dir: baseDir })
    });
    if (!response.ok) {
      if (!silentIfMissing) {
        const msg = await response.text();
        showEnmResult('warning', `Could not auto-load site list from ${baseDir}: ${msg || response.statusText}`);
      }
      return false;
    }
    const data = await response.json();
    if (!data || !data.ok || !Array.isArray(data.rows)) return false;
    siteListData = dedupeAndSortSiteRows(data.rows);
    siteListLoadedFromFile = siteListData.length > 0;
    const statusEl = document.getElementById('site-list-status');
    if (statusEl) statusEl.innerHTML = `<span class="text-success">Auto-loaded ${siteListData.length} sites from ${data.path}.</span>`;
    refreshScopeUfControls();
    return true;
  } catch (_) {
    return false;
  }
}

function setSiteListBusy(isBusy, message) {
  siteListBusy = !!isBusy;
  const btn = document.getElementById('btn-update-site-list');
  const statusEl = document.getElementById('site-list-status');
  if (btn) {
    btn.disabled = !!isBusy;
    btn.innerHTML = isBusy
      ? '<span class="spinner-border spinner-border-sm me-1" role="status" aria-hidden="true"></span>Uploading...'
      : '<i class="bi bi-folder2-open"></i> Select files and update';
  }
  if (statusEl && message) {
    statusEl.innerHTML = `<span class="text-muted">${message}</span>`;
  }
}

/** Build site list from CSV files (LTE + NR), dedupe. */
async function updateSiteListFromFolder(files) {
  const fileList = Array.from(files || []);
  if (!fileList.length) {
    showEnmResult('warning', 'Select one or more source files first.');
    return;
  }
  setSiteListBusy(true, `Uploading ${fileList.length} file(s)...`);

  // Preferred path: backend smart parser (supports CSV/TXT/XLSX/XLS and delimiter detection).
  try {
    const formData = new FormData();
    fileList.forEach(f => formData.append('files', f, f.name));
    const response = await fetch('http://127.0.0.1:8765/api/update-site-list', {
      method: 'POST',
      body: formData
    });
    if (response.ok) {
      const data = await response.json();
      if (data && data.ok && Array.isArray(data.rows)) {
        const incoming = dedupeAndSortSiteRows(data.rows);
        siteListData = mergeSiteListRows(siteListData, incoming);
        siteListLoadedFromFile = siteListData.length > 0;
        const statusEl = document.getElementById('site-list-status');
        if (statusEl) statusEl.innerHTML = `<span class="text-success">Updated: +${incoming.length} site(s), total ${siteListData.length}.</span>`;
        refreshScopeUfControls();

        const warnings = Array.isArray(data.warnings) ? data.warnings : [];
        const sources = Array.isArray(data.sources) ? data.sources : [];
        const summary = sources.length ? ` Sources: ${sources.join(' | ')}` : '';
        const warnSummary = warnings.length ? ` Warnings: ${warnings.slice(0, 3).join(' | ')}` : '';
        setSiteListBusy(true, 'Processing and saving site list...');
        try {
          const saved = await saveSiteListToServer(siteListData);
          if (statusEl) statusEl.innerHTML = `<span class="text-success">Updated: +${incoming.length} site(s), total ${siteListData.length}. Saved: ${saved.path}</span>`;
          showEnmResult('success', `Site list updated: +${incoming.length} site(s), total ${siteListData.length}. Saved to ${saved.path}.${summary}${warnSummary}`);
        } catch (saveErr) {
          if (statusEl) statusEl.innerHTML = `<span class="text-danger">Updated in memory, but save failed: ${saveErr.message}</span>`;
          showEnmResult('warning', `Site list updated in memory: +${incoming.length} site(s), total ${siteListData.length}, but could not save file: ${saveErr.message}${summary}${warnSummary}`);
        }
        setSiteListBusy(false);
        return;
      }
    }
  } catch (_) {
    // If backend is unavailable, fallback to local CSV/TXT parser below.
  }

  // Fallback path: local browser parsing (CSV/TXT only, legacy behavior).
  const lteFile = Array.from(files).find(f => f.name === 'EUtranCell_TDD_FDD.csv');
  const nrFiles = Array.from(files).filter(f => f.name.startsWith('Cellref_5G') && (f.name.endsWith('.csv') || f.name.endsWith('.txt')));
  if (!lteFile && nrFiles.length === 0) {
    setSiteListBusy(false);
    showEnmResult('warning', 'No compatible files found. Select EUtranCell_TDD_FDD and/or Cellref_5G files.');
    return;
  }
  const seen = new Set();
  const outRows = [];
  const enc = 'ISO-8859-1';

  if (lteFile) {
    const text = await readFileAsText(lteFile, enc);
    const data = parseCSV(text);
    for (const r of data) {
      const regional = (r.Regional || '').trim();
      const uf = (r.UF || '').trim().toUpperCase();
      const municipio = (r.MUNICIPIO || '').trim();
      const siteId = (r.eNB || '').trim();
      if (!siteId) continue;
      const key = regional + '\t' + uf + '\t' + municipio + '\t' + siteId + '\tLTE';
      if (seen.has(key)) continue;
      seen.add(key);
      outRows.push({ Regional: regional, UF: uf, MUNICIPIO: municipio, SiteID: siteId, Tech: 'LTE' });
    }
  }
  for (const file of nrFiles) {
    const text = await readFileAsText(file, enc);
    let data = file.name.endsWith('.csv') ? parseCSV(text) : parseSiteListTSV(text);
    if (!data.length && text.includes('\t')) data = parseSiteListTSV(text);
    for (const r of data) {
      const regional = (r.Regional || '').trim();
      const uf = (r.UF || '').trim().toUpperCase();
      const municipio = (r.MUNICIPIO || '').trim();
      const siteId = (r.SiteID || r.SiteId || '').trim();
      if (!siteId) continue;
      const key = regional + '\t' + uf + '\t' + municipio + '\t' + siteId + '\tNR';
      if (seen.has(key)) continue;
      seen.add(key);
      outRows.push({ Regional: regional, UF: uf, MUNICIPIO: municipio, SiteID: siteId, Tech: 'NR' });
    }
  }

  const incoming = dedupeAndSortSiteRows(outRows);
  siteListData = mergeSiteListRows(siteListData, incoming);
  siteListLoadedFromFile = siteListData.length > 0;
  const statusEl = document.getElementById('site-list-status');
  if (statusEl) statusEl.innerHTML = `<span class="text-success">Updated: +${incoming.length} site(s), total ${siteListData.length}.</span>`;
  refreshScopeUfControls();
  try {
    setSiteListBusy(true, 'Processing and saving site list...');
    const saved = await saveSiteListToServer(siteListData);
    if (statusEl) statusEl.innerHTML = `<span class="text-success">Updated: +${incoming.length} site(s), total ${siteListData.length}. Saved: ${saved.path}</span>`;
    showEnmResult('success', `Site list updated (local fallback): +${incoming.length} site(s), total ${siteListData.length}. Saved to ${saved.path}.`);
  } catch (saveErr) {
    if (statusEl) statusEl.innerHTML = `<span class="text-danger">Updated in memory, but save failed: ${saveErr.message}</span>`;
    showEnmResult('warning', `Site list updated (local fallback): +${incoming.length} site(s), total ${siteListData.length}, but could not save file: ${saveErr.message}`);
  } finally {
    setSiteListBusy(false);
  }
}

function parseSiteListTSV(text) {
  const raw = (text || '').replace(/^\uFEFF/, '').trim();
  const lines = raw.split(/\r?\n/).filter(l => l.trim());
  if (lines.length < 2) return [];
  const header = lines[0].split('\t').map(h => h.trim());
  const rows = [];
  for (let i = 1; i < lines.length; i++) {
    const cells = lines[i].split('\t');
    const row = {};
    header.forEach((h, j) => { row[h] = (cells[j] || '').trim(); });
    rows.push(row);
  }
  return rows;
}

function normalizeText(v) {
  return String(v || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .trim()
    .toUpperCase();
}

function normalizeSiteRow(row) {
  const techRaw = String((row && row.Tech) || '').trim().toUpperCase();
  let tech = techRaw;
  if (techRaw === '4G') tech = 'LTE';
  if (techRaw === '5G') tech = 'NR';
  return {
    Regional: String((row && row.Regional) || '').trim(),
    UF: String((row && row.UF) || '').trim().toUpperCase(),
    MUNICIPIO: String((row && row.MUNICIPIO) || '').trim(),
    SiteID: String((row && row.SiteID) || '').trim(),
    Tech: tech || 'LTE'
  };
}

function dedupeAndSortSiteRows(rows) {
  const out = [];
  const seen = new Set();
  (rows || []).forEach(r => {
    const row = normalizeSiteRow(r || {});
    if (!row.UF || !row.MUNICIPIO || !row.SiteID) return;
    const key = [row.UF, normalizeText(row.MUNICIPIO), row.SiteID.toUpperCase(), row.Tech].join('|');
    if (seen.has(key)) return;
    seen.add(key);
    out.push(row);
  });
  out.sort((a, b) =>
    a.UF.localeCompare(b.UF) ||
    a.MUNICIPIO.localeCompare(b.MUNICIPIO) ||
    a.SiteID.localeCompare(b.SiteID) ||
    a.Tech.localeCompare(b.Tech)
  );
  return out;
}

function mergeSiteListRows(existingRows, newRows) {
  return dedupeAndSortSiteRows([...(existingRows || []), ...(newRows || [])]);
}

function getAvailableUfsFromSiteList() {
  if (!siteListLoadedFromFile) return AVAILABLE_UFS.slice();
  const fromData = [...new Set(siteListData.map(r => (r.UF || '').toUpperCase().trim()).filter(Boolean))].sort();
  return fromData.length ? fromData : AVAILABLE_UFS.slice();
}

function refreshUfSelectOptions() {
  const ufSelect = document.getElementById('scope-uf-select');
  if (!ufSelect) return;
  const previous = (ufSelect.value || '').trim().toUpperCase();
  const ufs = getAvailableUfsFromSiteList();
  ufSelect.innerHTML = '<option value="">-- Use selected UF(s) --</option>' + ufs.map(u => `<option value="${u}">${u}</option>`).join('');
  if (previous && ufs.includes(previous)) ufSelect.value = previous;
}

function refreshScopeUfControls() {
  renderUfs();
  refreshUfSelectOptions();
  updateMunicipalityDatalist();
}

function loadSiteListFile() {
  const input = document.getElementById('site-list-file');
  const file = input && input.files[0];
  if (!file) {
    showEnmResult('warning', 'Choose a site list file first.');
    return;
  }
  const reader = new FileReader();
  reader.onload = function () {
    siteListData = dedupeAndSortSiteRows(parseSiteListTSV(reader.result));
    siteListLoadedFromFile = siteListData.length > 0;
    const statusEl = document.getElementById('site-list-status');
    if (statusEl) statusEl.innerHTML = `<span class="text-success">Loaded ${siteListData.length} sites.</span>`;
    refreshScopeUfControls();
    showEnmResult('success', `Site list loaded: ${siteListData.length} sites.`);
  };
  reader.readAsText(file, 'UTF-8'); // file was saved as UTF-8 (with BOM when downloaded from tool)
}

function getScope() {
  const r = document.querySelector('input[name="scope"]:checked');
  return (r && r.value) || 'uf';
}

function getSitesString() {
  const scope = getScope();
  if (scope === 'uf') {
    const ufs = getSelectedUfs();
    return ufs.map(uf => `*_${uf}`).join(';');
  }
  if (scope === 'list') {
    const ta = document.getElementById('scope-list-textarea');
    const text = (ta && ta.value || '').trim();
    const sites = text.split(/[\n;,]+/).map(s => s.trim()).filter(Boolean);
    return [...new Set(sites)].join(';');
  }
  if (scope === 'municipality') {
    const ufSelectedInCity = (document.getElementById('scope-uf-select') && document.getElementById('scope-uf-select').value || '').trim().toUpperCase();
    const selectedUfs = [...new Set([...getSelectedUfs(), ...(ufSelectedInCity ? [ufSelectedInCity] : [])])];
    const mun = (document.getElementById('scope-municipality-input') && document.getElementById('scope-municipality-input').value || '').trim();
    const selectedCitiesNorm = selectedMunicipalities.map(normalizeText);
    const lte = document.getElementById('scope-tech-lte') && document.getElementById('scope-tech-lte').checked;
    const nr = document.getElementById('scope-tech-nr') && document.getElementById('scope-tech-nr').checked;
    if (!selectedUfs.length) return '';
    if (!selectedCitiesNorm.length && !mun) return '';
    const filtered = siteListData.filter(r => {
      if (!selectedUfs.includes((r.UF || '').toUpperCase())) return false;
      if (selectedCitiesNorm.length) {
        if (!selectedCitiesNorm.includes(normalizeText(r.MUNICIPIO))) return false;
      } else if (!normalizeText(r.MUNICIPIO).includes(normalizeText(mun))) {
        return false;
      }
      const tech = (r.Tech || '').toUpperCase();
      if (tech === 'LTE' && !lte) return false;
      if (tech === 'NR' && !nr) return false;
      return true;
    });
    const ids = [...new Set(filtered.map(r => (r.SiteID || '').trim()).filter(Boolean))];
    return ids.join(';');
  }
  return '';
}

function updateScopePanels() {
  const scope = getScope();
  document.getElementById('scope-uf-panel').style.display = scope === 'uf' ? 'block' : 'none';
  document.getElementById('scope-municipality-panel').style.display = scope === 'municipality' ? 'block' : 'none';
  document.getElementById('scope-list-panel').style.display = scope === 'list' ? 'block' : 'none';
  if (scope === 'municipality') updateMunicipalityCount();
}

function updateMunicipalityCount() {
  const s = getSitesString();
  const count = s ? s.split(';').filter(Boolean).length : 0;
  const el = document.getElementById('scope-municipality-count');
  if (el) el.textContent = count ? `${count} site(s) selected.` : 'Select UF(s) and add one or more cities.';
}

function pruneSelectedMunicipalities(selectedUfs) {
  if (!selectedMunicipalities.length) return;
  if (!selectedUfs.length) return;
  const kept = selectedMunicipalities.filter(city =>
    siteListData.some(r =>
      selectedUfs.includes((r.UF || '').toUpperCase()) &&
      normalizeText(r.MUNICIPIO) === normalizeText(city)
    )
  );
  selectedMunicipalities = kept;
}

function renderSelectedMunicipalities() {
  const box = document.getElementById('municipality-selected');
  if (!box) return;
  if (!selectedMunicipalities.length) {
    box.innerHTML = '';
    return;
  }
  const chips = selectedMunicipalities.map(c => (
    `<span class="badge text-bg-primary me-1 mb-1">${c} ` +
    `<button type="button" class="btn-close btn-close-white ms-1 city-remove-btn" aria-label="Remove" data-city="${c}" style="font-size:0.55rem;"></button></span>`
  )).join('');
  box.innerHTML = `<div class="mb-1">${chips}</div><button type="button" class="btn btn-outline-secondary btn-sm" id="btn-clear-cities">Clear cities</button>`;
  box.querySelectorAll('.city-remove-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      const city = btn.getAttribute('data-city') || '';
      selectedMunicipalities = selectedMunicipalities.filter(c => normalizeText(c) !== normalizeText(city));
      renderSelectedMunicipalities();
      updateMunicipalityCount();
    });
  });
  const clearBtn = document.getElementById('btn-clear-cities');
  if (clearBtn) {
    clearBtn.addEventListener('click', () => {
      selectedMunicipalities = [];
      renderSelectedMunicipalities();
      updateMunicipalityCount();
    });
  }
}

function addMunicipalitySelection(city) {
  const c = (city || '').trim();
  if (!c) return;
  if (selectedMunicipalities.some(x => normalizeText(x) === normalizeText(c))) return;
  selectedMunicipalities.push(c);
  selectedMunicipalities.sort((a, b) => a.localeCompare(b));
  const input = document.getElementById('scope-municipality-input');
  if (input) input.value = '';
  renderSelectedMunicipalities();
  updateMunicipalityDatalist();
}

function getSelectedUfsForCityScope() {
  const ufSelectedInCity = (document.getElementById('scope-uf-select') && document.getElementById('scope-uf-select').value || '').trim().toUpperCase();
  return [...new Set([...getSelectedUfs(), ...(ufSelectedInCity ? [ufSelectedInCity] : [])])];
}

function resolveCityCandidate(rawQuery) {
  const q = (rawQuery || '').trim();
  if (!q) return '';
  const selectedUfs = getSelectedUfsForCityScope();
  const cities = [...new Set(
    siteListData
      .filter(r => !selectedUfs.length || selectedUfs.includes((r.UF || '').toUpperCase()))
      .map(r => (r.MUNICIPIO || '').trim())
      .filter(Boolean)
  )];
  const nq = normalizeText(q);
  const exact = cities.find(c => normalizeText(c) === nq);
  if (exact) return exact;
  const startsWithList = cities.filter(c => normalizeText(c).startsWith(nq));
  if (startsWithList.length) {
    startsWithList.sort((a, b) => a.length - b.length || a.localeCompare(b));
    return startsWithList[0];
  }
  const contains = cities.find(c => normalizeText(c).includes(nq));
  if (contains) return contains;
  return q;
}

function updateMunicipalityDatalist() {
  const ufSelectedInCity = (document.getElementById('scope-uf-select') && document.getElementById('scope-uf-select').value || '').trim().toUpperCase();
  const selectedUfs = [...new Set([...getSelectedUfs(), ...(ufSelectedInCity ? [ufSelectedInCity] : [])])];
  pruneSelectedMunicipalities(selectedUfs);
  renderSelectedMunicipalities();
  const q = (document.getElementById('scope-municipality-input') && document.getElementById('scope-municipality-input').value || '').trim();
  const list = document.getElementById('municipality-datalist');
  const sug = document.getElementById('municipality-suggestions');
  if (!list) return;
  list.innerHTML = '';
  if (sug) sug.innerHTML = '';
  if (!selectedUfs.length || siteListData.length === 0) {
    updateMunicipalityCount();
    return;
  }
  const nq = normalizeText(q);
  const allCities = [...new Set(
    siteListData
      .filter(r => selectedUfs.includes((r.UF || '').toUpperCase()))
      .map(r => (r.MUNICIPIO || '').trim())
      .filter(Boolean)
  )];
  const startsWith = allCities.filter(c => normalizeText(c).startsWith(nq)).sort();
  const contains  = allCities.filter(c => !normalizeText(c).startsWith(nq) && normalizeText(c).includes(nq)).sort();
  const matches = nq ? [...startsWith, ...contains] : allCities.sort();
  matches.slice(0, 100).forEach(m => {
    const opt = document.createElement('option');
    opt.value = m;
    list.appendChild(opt);
  });
  if (sug) {
    const quick = matches.slice(0, 12);
    if (quick.length) {
      sug.innerHTML = quick.map(m => `<button type="button" class="btn btn-outline-secondary btn-sm me-1 mb-1 mun-suggest-btn" data-city="${m}">${m}</button>`).join('');
      sug.querySelectorAll('.mun-suggest-btn').forEach(btn => {
        btn.addEventListener('click', () => addMunicipalitySelection(btn.getAttribute('data-city') || ''));
      });
    }
  }
  updateMunicipalityCount();
}

// ---------- ENM rows (editable list: add / edit / remove / import / export) ----------

/** Snapshot of what is typed in the ENM table, so a re-render does not lose it. */
function _captureEnmRowState() {
  const state = {};
  getEnmList().forEach(({ id }) => {
    const u = document.getElementById(`enm-username-${id}`);
    if (!u) return;
    state[id] = {
      username: u.value,
      password: document.getElementById(`enm-password-${id}`).value,
      include: document.getElementById(`enm-include-${id}`).checked
    };
  });
  return state;
}

function _enmHost(url) {
  try { return new URL(url).host; } catch (_) { return url; }
}

function renderEnmRows(state) {
  const tbody = document.getElementById('enm-rows');
  if (!tbody) return;
  const list = getEnmList();
  if (!list.length) {
    tbody.innerHTML = '<tr><td colspan="5" class="text-center text-muted small py-3">' +
      'No ENMs configured — use <strong>Add ENM</strong> or <strong>Import</strong> to add your operator\'s ENMs.</td></tr>';
    return;
  }
  tbody.innerHTML = list.map(({ id, url }) => `
    <tr>
      <td class="align-middle enm-name-cell">
        <div class="fw-bold">${_fbEsc(id)}</div>
        <div class="enm-url" title="${_fbEsc(url)}">${_fbEsc(_enmHost(url))}</div>
      </td>
      <td class="text-center align-middle">
        <input class="form-check-input" type="checkbox" id="enm-include-${id}" data-enm-id="${id}" title="Include this ENM in dump">
      </td>
      <td class="align-middle">
        <input type="text" class="form-control form-control-sm" id="enm-username-${id}" placeholder="Leave blank if not used">
      </td>
      <td class="align-middle">
        <input type="password" class="form-control form-control-sm" id="enm-password-${id}" placeholder="Password">
      </td>
      <td class="align-middle text-end enm-actions">
        <button type="button" class="btn btn-link btn-sm p-0" data-enm-action="edit" data-enm-id="${id}" title="Edit name / URL"><i class="bi bi-pencil"></i></button>
        <button type="button" class="btn btn-link btn-sm p-0 text-danger" data-enm-action="remove" data-enm-id="${id}" title="Remove ENM"><i class="bi bi-trash"></i></button>
      </td>
    </tr>`).join('');
  if (state) {
    Object.entries(state).forEach(([id, s]) => {
      const u = document.getElementById(`enm-username-${id}`);
      if (!u) return;
      u.value = s.username;
      document.getElementById(`enm-password-${id}`).value = s.password;
      document.getElementById(`enm-include-${id}`).checked = s.include;
    });
  }
}

/** Normalize and validate an ENM entry. Returns { enm } or { error }. */
function _validateEnm(id, url, originalId) {
  id = String(id || '').trim().toUpperCase();
  url = String(url || '').trim();
  if (!ENM_ID_RE.test(id)) return { error: 'ENM name: letters, digits, "-" or "_" only (max 32 characters).' };
  if (!/^https?:\/\/[^\s/]+/i.test(url)) return { error: 'URL must start with https:// — e.g. https://enm01.operator.com/' };
  if (!url.endsWith('/')) url += '/';
  if (getEnmList().some(e => e.id === id && e.id !== originalId)) return { error: `ENM "${id}" already exists.` };
  return { enm: { id, url } };
}

/** Rename the ENM key inside every saved profile, so credentials follow the new name. */
function _renameEnmInProfiles(oldId, newId) {
  const data = loadProfilesData();
  let changed = false;
  (data.profiles || []).forEach(p => {
    if (p.enms && p.enms[oldId] && !p.enms[newId]) {
      p.enms[newId] = p.enms[oldId];
      delete p.enms[oldId];
      changed = true;
    }
  });
  if (changed) saveProfilesData(data);
}

function removeEnm(id) {
  if (!confirm(`Remove ENM "${id}" from the list?`)) return;
  const state = _captureEnmRowState();
  saveEnmList(getEnmList().filter(e => e.id !== id));
  renderEnmRows(state);
  closeEnmForm();
}

function closeEnmForm() {
  const form = document.getElementById('enm-form');
  if (form) form.remove();
}

/** Inline form to add a new ENM (editId empty) or edit an existing one. */
function showEnmForm(editId) {
  closeEnmForm();
  const container = document.getElementById('enm-form-container');
  if (!container) return;
  const current = editId ? getEnmList().find(e => e.id === editId) : null;
  const form = document.createElement('div');
  form.id = 'enm-form';
  form.className = 'enm-form mt-2';
  form.innerHTML = `
    <div class="small fw-bold mb-1">${current ? `Edit ENM ${_fbEsc(current.id)}` : 'Add ENM'}</div>
    <div class="row g-2 align-items-end">
      <div class="col-auto">
        <label class="form-label small mb-1" for="enm-form-id">Name</label>
        <input type="text" id="enm-form-id" class="form-control form-control-sm" placeholder="ENM01" style="width:130px" maxlength="32">
      </div>
      <div class="col">
        <label class="form-label small mb-1" for="enm-form-url">URL</label>
        <input type="text" id="enm-form-url" class="form-control form-control-sm" placeholder="https://enm01.operator.com/">
      </div>
      <div class="col-auto d-flex gap-1">
        <button type="button" class="btn btn-primary btn-sm" id="enm-form-save"><i class="bi bi-check-lg"></i> ${current ? 'Save' : 'Add'}</button>
        <button type="button" class="btn btn-outline-secondary btn-sm" id="enm-form-cancel">Cancel</button>
      </div>
    </div>
    <div class="text-danger small mt-1" id="enm-form-error"></div>`;
  container.appendChild(form);

  const idEl = document.getElementById('enm-form-id');
  const urlEl = document.getElementById('enm-form-url');
  if (current) { idEl.value = current.id; urlEl.value = current.url; }
  idEl.addEventListener('input', () => { idEl.value = idEl.value.toUpperCase(); });

  const submit = () => {
    const res = _validateEnm(idEl.value, urlEl.value, current ? current.id : null);
    if (res.error) { document.getElementById('enm-form-error').textContent = res.error; return; }
    const state = _captureEnmRowState();
    const list = getEnmList();
    if (current) {
      list[list.findIndex(e => e.id === current.id)] = res.enm;
      if (res.enm.id !== current.id) {
        if (state[current.id]) { state[res.enm.id] = state[current.id]; delete state[current.id]; }
        _renameEnmInProfiles(current.id, res.enm.id);
      }
    } else {
      list.push(res.enm);
    }
    saveEnmList(list);
    renderEnmRows(state);
    closeEnmForm();
    showEnmResult('success', current ? `ENM "${res.enm.id}" updated.` : `ENM "${res.enm.id}" added.`);
  };
  document.getElementById('enm-form-save').addEventListener('click', submit);
  document.getElementById('enm-form-cancel').addEventListener('click', closeEnmForm);
  form.addEventListener('keydown', e => {
    if (e.key === 'Enter') { e.preventDefault(); submit(); }
    if (e.key === 'Escape') closeEnmForm();
  });
  idEl.focus();
}

/** Download the ENM list (names + URLs only, never credentials) as JSON. */
function exportEnmList() {
  const payload = { type: 'downloader-enm-list', version: 1, enms: getEnmList().map(({ id, url }) => ({ id, url })) };
  const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = 'enm_list.json';
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(a.href), 1000);
  showEnmResult('success', `Exported ${payload.enms.length} ENM(s) to enm_list.json (no passwords included).`);
}

/** Import ENMs from JSON ({enms:[...]} or a plain array). Same name → URL updated; new names → added. */
async function importEnmList(file) {
  let items;
  try {
    const parsed = JSON.parse(await file.text());
    items = Array.isArray(parsed) ? parsed : parsed.enms;
    if (!Array.isArray(items)) throw new Error('no "enms" list found');
  } catch (e) {
    showEnmResult('danger', `Could not read ${_fbEsc(file.name)}: ${_fbEsc(e.message)}`);
    return;
  }
  const state = _captureEnmRowState();
  const list = getEnmList();
  let added = 0, updated = 0;
  const bad = [];
  items.forEach(item => {
    const id = String((item && item.id) || '').trim().toUpperCase();
    const res = _validateEnm(id, item && item.url, id);  // same name allowed → update
    if (res.error) { bad.push(id || '?'); return; }
    const idx = list.findIndex(e => e.id === res.enm.id);
    if (idx >= 0) { list[idx] = res.enm; updated++; }
    else { list.push(res.enm); added++; }
  });
  saveEnmList(list);
  renderEnmRows(state);
  let msg = `Imported: ${added} added, ${updated} updated.`;
  if (bad.length) msg += ` Skipped (invalid name/URL): ${_fbEsc(bad.join(', '))}.`;
  showEnmResult(bad.length ? 'warning' : 'success', msg);
}

function initEnmListControls() {
  const tbody = document.getElementById('enm-rows');
  if (tbody) tbody.addEventListener('click', e => {
    const btn = e.target.closest('[data-enm-action]');
    if (!btn) return;
    if (btn.dataset.enmAction === 'edit') showEnmForm(btn.dataset.enmId);
    else if (btn.dataset.enmAction === 'remove') removeEnm(btn.dataset.enmId);
  });
  const btnAdd = document.getElementById('btn-add-enm');
  if (btnAdd) btnAdd.addEventListener('click', () => showEnmForm());
  const btnExport = document.getElementById('btn-export-enms');
  if (btnExport) btnExport.addEventListener('click', exportEnmList);
  const fileInput = document.getElementById('enm-import-input');
  const btnImport = document.getElementById('btn-import-enms');
  if (btnImport && fileInput) {
    btnImport.addEventListener('click', () => fileInput.click());
    fileInput.addEventListener('change', () => {
      if (fileInput.files[0]) importEnmList(fileInput.files[0]);
      fileInput.value = '';
    });
  }
}

/** Retorna lista de ENMs selecionados para dump (incluir marcado e username preenchido). */
function getSelectedEnms() {
  const list = [];
  getEnmList().forEach(({ id, url }) => {
    const include = document.getElementById(`enm-include-${id}`);
    const username = (document.getElementById(`enm-username-${id}`) || {}).value.trim();
    const password = (document.getElementById(`enm-password-${id}`) || {}).value;
    if (include && include.checked && username) {
      list.push({ id, nameShort: enmShortName(id), url, username, password });
    }
  });
  return list;
}

/** All ENM form data (for saving in profile). */
function getEnmFormData() {
  const enms = {};
  getEnmList().forEach(({ id }) => {
    const u = document.getElementById(`enm-username-${id}`);
    const p = document.getElementById(`enm-password-${id}`);
    enms[id] = {
      username: u ? u.value.trim() : '',
      password: p ? p.value : ''
    };
  });
  return enms;
}

function setEnmFormData(enms) {
  if (!enms) return;
  getEnmList().forEach(({ id }) => {
    const cred = enms[id];
    if (!cred) return;
    const u = document.getElementById(`enm-username-${id}`);
    const p = document.getElementById(`enm-password-${id}`);
    if (u) u.value = cred.username || '';
    if (p) p.value = cred.password || '';
  });
}

// ---------- Profiles (localStorage): credenciais por ENM ----------
function loadProfilesData() {
  try {
    const raw = localStorage.getItem(STORAGE_PROFILES);
    return raw ? JSON.parse(raw) : { profiles: [], last_used_profile: null };
  } catch {
    return { profiles: [], last_used_profile: null };
  }
}

function saveProfilesData(data) {
  try {
    localStorage.setItem(STORAGE_PROFILES, JSON.stringify(data));
  } catch (e) {
    showEnmResult('danger', 'Could not save profiles.');
  }
}

function loadEnmProfiles() {
  const data = loadProfilesData();
  const sel = document.getElementById('enm-profile-select');
  if (!sel) return;
  const currentVal = sel.value;
  sel.innerHTML = '<option value="">-- Profile --</option>';
  (data.profiles || []).forEach(p => {
    const opt = document.createElement('option');
    opt.value = p.name;
    opt.textContent = p.name;
    sel.appendChild(opt);
  });
  if (data.last_used_profile && data.profiles.some(p => p.name === data.last_used_profile)) {
    sel.value = data.last_used_profile;
    const profile = data.profiles.find(p => p.name === data.last_used_profile);
    if (profile) applyProfileToForm(profile);
  } else if (currentVal) sel.value = currentVal;
}

function applyProfileToForm(profile) {
  setEnmFormData(profile.enms);
  const o = document.getElementById('enm-output-dir');
  if (o) {
    o.value = profile.output_dir || profile.dump_output_dir || o.value;
    var v = o.value.trim();
    if (v) try { localStorage.setItem(STORAGE_LAST_OUTPUT_DIR, v); } catch (_) {}
  }
}

function saveEnmProfile() {
  let name = document.getElementById('enm-profile-select').value;
  if (!name) {
    name = prompt('Profile name:');
    if (!name) return;
  }
  const enms = getEnmFormData();
  const outputDir = document.getElementById('enm-output-dir').value.trim();
  const data = loadProfilesData();
  const profile = { name, enms, output_dir: outputDir };
  let profiles = data.profiles || [];
  const idx = profiles.findIndex(p => p.name === name);
  if (idx >= 0) profiles[idx] = profile;
  else profiles.push(profile);
  data.profiles = profiles;
  data.last_used_profile = name;
  saveProfilesData(data);
  loadEnmProfiles();
  showEnmResult('success', `Profile "${name}" saved.`);
}

function deleteEnmProfile() {
  const name = document.getElementById('enm-profile-select').value;
  if (!name) {
    showEnmResult('warning', 'Select a profile.');
    return;
  }
  if (!confirm(`Delete profile "${name}"?`)) return;
  const data = loadProfilesData();
  data.profiles = (data.profiles || []).filter(p => p.name !== name);
  if (data.last_used_profile === name) data.last_used_profile = null;
  saveProfilesData(data);
  loadEnmProfiles();
  setEnmFormData(Object.fromEntries(getEnmList().map(e => [e.id, {}])));
  showEnmResult('info', `Profile "${name}" deleted.`);
}

// ---------- UF Selection ----------
function renderUfs() {
  const container = document.getElementById('uf-checkboxes');
  if (!container) return;
  const current = new Set(getSelectedUfs());
  const ufs = getAvailableUfsFromSiteList();
  container.innerHTML = ufs.map(uf => `
    <div class="form-check form-check-inline">
      <input class="form-check-input" type="checkbox" id="uf-${uf}" value="${uf}" ${current.has(uf) ? 'checked' : ''}>
      <label class="form-check-label small" for="uf-${uf}">${uf}</label>
    </div>
  `).join('');
  container.querySelectorAll('input[type="checkbox"]').forEach(cb => {
    cb.addEventListener('change', updateMunicipalityDatalist);
  });
}

function getSelectedUfs() {
  const values = [];
  document.querySelectorAll('#uf-checkboxes input[type="checkbox"]:checked').forEach(cb => values.push(cb.value));
  return values;
}

function selectAllUfs() {
  document.querySelectorAll('#uf-checkboxes input[type="checkbox"]').forEach(cb => { cb.checked = true; });
  updateMunicipalityDatalist();
}

function clearAllUfs() {
  document.querySelectorAll('#uf-checkboxes input[type="checkbox"]').forEach(cb => { cb.checked = false; });
  updateMunicipalityDatalist();
}

// ---------- MO Selection ----------
function renderMoDefaultList() {
  const container = document.getElementById('mo-default-list');
  if (!container) return;
  container.innerHTML = DEFAULT_MOS.map(mo => `
    <div class="form-check form-check-inline py-1 mo-item" style="font-size: 0.82rem; min-width: 12rem;" data-mo-name="${mo.id.toLowerCase()}">
      <input class="form-check-input mo-default-cb" type="checkbox" id="mo-cb-${mo.id}" data-mo-id="${mo.id}">
      <label class="form-check-label" for="mo-cb-${mo.id}"><code>${mo.id}</code></label>
    </div>
  `).join('');
  container.addEventListener('change', updateMoCount);
}

function getSelectedMos() {
  const mos = [];
  document.querySelectorAll('.mo-default-cb:checked').forEach(cb => {
    const id = cb.getAttribute('data-mo-id');
    if (id) mos.push(id);
  });
  customMos.forEach(mo => {
    const id = mo.replace(/\.\*;?$/, '').replace(/;$/, '');
    if (id && !mos.includes(id)) mos.push(id);
  });
  return mos;
}

function setAllMoCheckboxes(checked) {
  document.querySelectorAll('.mo-default-cb').forEach(cb => { cb.checked = !!checked; });
  updateMoCount();
}

function selectMoB() {
  document.querySelectorAll('.mo-default-cb').forEach(cb => {
    const id = cb.getAttribute('data-mo-id');
    cb.checked = MOB_MOS.some(m => m.toLowerCase() === (id || '').toLowerCase());
  });
  updateMoCount();
}

function filterMoList(query) {
  const q = (query || '').toLowerCase().trim();
  document.querySelectorAll('#mo-default-list .mo-item').forEach(el => {
    const name = el.getAttribute('data-mo-name') || '';
    el.style.display = (!q || name.includes(q)) ? '' : 'none';
  });
}

function updateMoCount() {
  const total = document.querySelectorAll('.mo-default-cb').length;
  const selected = document.querySelectorAll('.mo-default-cb:checked').length;
  const badge = document.getElementById('mo-count-badge');
  if (badge) badge.textContent = `${selected} / ${total}`;
}

function addCustomMo() {
  const input = document.getElementById('mo-custom-input');
  const value = (input && input.value || '').trim();
  if (!value) return;
  if (customMos.includes(value) || DEFAULT_MOS.some(m => m.pattern === value || m.id === value)) {
    showEnmResult('warning', 'This MO is already included.');
    return;
  }
  customMos.push(value);
  input.value = '';
  renderCustomMos();
}

function removeCustomMo(index) {
  customMos.splice(index, 1);
  renderCustomMos();
}

function renderCustomMos() {
  const container = document.getElementById('mo-custom-list');
  if (!container) return;
  if (customMos.length === 0) {
    container.innerHTML = '';
    return;
  }
  container.innerHTML = customMos.map((mo, i) => `
    <div class="d-flex align-items-center gap-2 py-1" style="font-size: 0.82rem;">
      <i class="bi bi-plus-circle-fill text-primary" style="font-size: 0.7rem;"></i>
      <code class="text-dark">${mo}</code>
      <button class="btn btn-link btn-sm text-danger p-0 ms-auto" type="button" data-remove-mo="${i}" title="Remove">
        <i class="bi bi-x-lg" style="font-size: 0.7rem;"></i>
      </button>
    </div>
  `).join('');
  container.querySelectorAll('[data-remove-mo]').forEach(btn => {
    btn.addEventListener('click', () => removeCustomMo(parseInt(btn.getAttribute('data-remove-mo'), 10)));
  });
}

// ---------- Command generation ----------
function generateEnmCommand() {
  const scope = getScope();
  const sitesString = getSitesString();
  if (!sitesString) {
    if (scope === 'uf') showEnmResult('warning', 'Select at least one UF.');
    else if (scope === 'municipality') showEnmResult('warning', 'Load site list, then select UF(s) and city.');
    else showEnmResult('warning', 'Enter at least one site ID.');
    return;
  }
  const now = new Date();
  const timestamp = now.getFullYear() +
    String(now.getMonth() + 1).padStart(2, '0') +
    String(now.getDate()).padStart(2, '0') + '_' +
    String(now.getHours()).padStart(2, '0') +
    String(now.getMinutes()).padStart(2, '0') +
    String(now.getSeconds()).padStart(2, '0');
  const jobName = `downloader_${timestamp}`;
  const command = `cmedit export -n ${sitesString} --filetype 3GPP -jn ${jobName} -f file:mos_downloader.txt`;
  const textarea = document.getElementById('enm-command');
  if (textarea) {
    textarea.value = command;
    textarea.removeAttribute('readonly');
  }
  const selected = getSelectedEnms();
  const msg = selected.length > 0
    ? `Command generated. Each selected ENM will use its own job name (e.g. BARA_${timestamp}). (${selected.length} ENM(s) selected.)`
    : `Command generated. Job: ${jobName}. Check ENMs and fill user/password to run on multiple ENMs.`;
  showEnmResult('success', msg);
}

function copyEnmCommand() {
  const cmd = document.getElementById('enm-command');
  if (!cmd || !cmd.value.trim()) {
    showEnmResult('warning', 'Generate the command first.');
    return;
  }
  cmd.select();
  navigator.clipboard.writeText(cmd.value).then(() => {
    showEnmResult('info', 'Command copied.');
  }).catch(() => {
    showEnmResult('warning', 'Copy manually.');
  });
}

// ---------- Export JSON for Python script ----------
function openExportSiteListModal() {
  const sitesStr = getSitesString();
  const ids = sitesStr ? sitesStr.split(';').filter(Boolean) : [];
  if (!ids.length) {
    showEnmResult('warning', 'No sites in scope. Configure scope and generate command before exporting.');
    return;
  }
  const dirEl  = document.getElementById('export-sl-dir');
  const nameEl = document.getElementById('export-sl-filename');
  const countEl = document.getElementById('export-sl-count');
  if (dirEl)  dirEl.value  = localStorage.getItem(STORAGE_EXPORT_SL_DIR)  || '';
  if (nameEl) nameEl.value = localStorage.getItem(STORAGE_EXPORT_SL_NAME) || 'sites_list.txt';
  if (countEl) countEl.textContent = `${ids.length} site(s) will be exported.`;
  bootstrap.Modal.getOrCreateInstance(document.getElementById('exportSiteListModal')).show();
}

async function confirmExportSiteList() {
  const dir  = (document.getElementById('export-sl-dir')  && document.getElementById('export-sl-dir').value  || '').trim();
  const name = (document.getElementById('export-sl-filename') && document.getElementById('export-sl-filename').value || '').trim() || 'sites_list.txt';
  if (!dir) { alert('Please enter a directory.'); return; }
  const sitesStr = getSitesString();
  const ids = sitesStr ? sitesStr.split(';').filter(Boolean) : [];
  if (!ids.length) { alert('No sites to export.'); return; }
  const filePath = dir.replace(/[/\\]+$/, '') + '/' + name;
  const btnConfirm = document.getElementById('btn-export-sl-confirm');
  const countEl = document.getElementById('export-sl-count');
  try {
    if (btnConfirm) { btnConfirm.disabled = true; btnConfirm.innerHTML = '<i class="bi bi-hourglass-split"></i> Exporting...'; }
    const resp = await fetch('/api/export-site-ids', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ file_path: filePath, ids })
    });
    const data = await resp.json();
    if (data.ok) {
      try { localStorage.setItem(STORAGE_EXPORT_SL_DIR, dir); localStorage.setItem(STORAGE_EXPORT_SL_NAME, name); } catch (_) {}
      if (btnConfirm) { btnConfirm.innerHTML = '<i class="bi bi-check-lg"></i> Done!'; }
      if (countEl) countEl.innerHTML = `<span class="text-success fw-bold">✓ ${data.count} sites exported to ${data.path}</span>`;
      setTimeout(() => {
        bootstrap.Modal.getOrCreateInstance(document.getElementById('exportSiteListModal')).hide();
        if (btnConfirm) { btnConfirm.disabled = false; btnConfirm.innerHTML = '<i class="bi bi-download"></i> Export'; }
      }, 1500);
    } else {
      if (btnConfirm) { btnConfirm.disabled = false; btnConfirm.innerHTML = '<i class="bi bi-download"></i> Export'; }
      alert(`Export failed: ${data.error}`);
    }
  } catch (e) {
    if (btnConfirm) { btnConfirm.disabled = false; btnConfirm.innerHTML = '<i class="bi bi-download"></i> Export'; }
    alert(`Export failed: ${e.message}`);
  }
}

function exportForScript() {
  if (!getSitesString()) {
    showEnmResult('warning', 'Select scope (UF, city, or site list) and generate command before export.');
    return;
  }
  if (getSelectedEnms().length === 0) {
    showEnmResult('warning', 'Check and fill user/password for at least one ENM.');
    return;
  }
  if (!document.getElementById('enm-command').value.trim()) {
    showEnmResult('warning', 'Generate the command before export.');
    return;
  }
  const config = getExportConfig();
  const blob = new Blob([JSON.stringify(config, null, 2)], { type: 'application/json' });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = `downloader_dump_config_${new Date().toISOString().slice(0, 10)}_${Date.now()}.json`;
  a.click();
  URL.revokeObjectURL(a.href);
  showEnmResult('success', `Config saved. You can run run_dump.bat <this file> in a terminal, or use Execute Dump when the tool is opened via START_DOWNLOADER.bat.`);
  appendLog(`[${new Date().toLocaleTimeString()}] Config exported. Run run_dump.bat <config.json> in a terminal, or use Execute Dump if you opened the tool with START_DOWNLOADER.bat.`);
}

/** Build config object for export or for API (same shape as exported JSON). */
function getExportConfig() {
  const sitesString = getSitesString();
  const selectedEnms = getSelectedEnms();
  const commandTemplate = document.getElementById('enm-command').value.trim();
  const outputDir = document.getElementById('enm-output-dir').value.trim();
  return {
    version: 1,
    output_dir: outputDir || 'C:/eNB_Fake/data/input',
    mos_file: 'mos_downloader.txt',
    command_template: commandTemplate,
    sites_string: sitesString,
    scope: getScope(),
    selected_ufs: getScope() === 'uf' ? getSelectedUfs() : [],
    selected_mos: getSelectedMos(),
    enms: selectedEnms.map(e => ({
      id: e.id,
      name_short: e.nameShort,
      url: e.url,
      username: e.username,
      password: e.password
    })),
    exported_at: new Date().toISOString()
  };
}

// ---------- Logs panel ----------
function appendLog(text) {
  const el = document.getElementById('dump-logs');
  if (!el) return;
  const line = (typeof text === 'string' ? text : '') + '\n';
  el.value += line;
  el.scrollTop = el.scrollHeight;
}

function clearLogs() {
  const el = document.getElementById('dump-logs');
  if (el) el.value = '';
}

/** Get path string from a folder file input (webkitdirectory). Browsers may return C:\fakepath\Name. */
function getPathFromFolderInput(inputEl) {
  if (!inputEl || !inputEl.files || inputEl.files.length === 0) return '';
  const first = inputEl.files[0];
  // Desktop shells may expose absolute path on File objects.
  if (first && first.path) {
    const dir = dirnamePath(first.path);
    if (dir) return dir.replace(/\\/g, '/');
  }
  if (inputEl.value && !/fakepath/i.test(inputEl.value)) {
    return inputEl.value.replace(/\\/g, '/');
  }
  if (first && first.webkitRelativePath) {
    const seg = first.webkitRelativePath.split(/[/\\]/)[0];
    return seg || '';
  }
  return '';
}

// ---------- File / Folder Browser Modal (Explorer-style, server-side listing) ----------
// Double-click opens a folder; in files mode a click toggles a file and the
// selection survives navigation, so files can be picked from several folders.
const _fb = {
  mode: 'folder', exts: [], path: '', parent: null, entries: [], visible: [],
  selected: new Map(), folderPick: null, resolve: null, placesLoaded: false
};

function _fbEsc(s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

function formatBytes(n) {
  if (!n) return '';
  const units = ['B', 'KB', 'MB', 'GB', 'TB'];
  let i = 0;
  let v = n;
  while (v >= 1024 && i < units.length - 1) { v /= 1024; i++; }
  return (i === 0 ? v : v.toFixed(v < 10 ? 1 : 0)) + ' ' + units[i];
}

function _fbFmtDate(t) {
  return new Date(t * 1000).toLocaleString('sv').slice(0, 16);
}

function _fbFileIcon(name) {
  const n = name.toLowerCase();
  if (n.endsWith('.zip')) return 'bi-file-earmark-zip-fill fb-ic-zip';
  if (n.endsWith('.xml') || n.endsWith('.xml.gz')) return 'bi-file-earmark-code-fill fb-ic-xml';
  return 'bi-file-earmark fb-ic-file';
}

function _fbAccepts(name) {
  const n = name.toLowerCase();
  return _fb.exts.some(e => n.endsWith(e));
}

function _fbPick(e) {
  return { path: e.path, name: e.name, size: e.size || 0 };
}

async function _fbLoadPlaces() {
  if (_fb.placesLoaded) return;
  const box = document.getElementById('fb-places');
  try {
    const d = await (await fetch('/api/local/places')).json();
    box.innerHTML = (d.places || []).map(p =>
      `<button type="button" class="fb-place" data-path="${_fbEsc(p.path)}" title="${_fbEsc(p.path)}">` +
      `<i class="bi ${_fbEsc(p.icon)}"></i>${_fbEsc(p.label)}</button>`).join('');
    box.querySelectorAll('.fb-place').forEach(b => b.addEventListener('click', () => _fbNavigate(b.dataset.path)));
    _fb.placesLoaded = true;
  } catch (_) {
    box.innerHTML = '';
  }
}

async function _fbNavigate(path, nearest) {
  const tbody = document.getElementById('fb-tbody');
  tbody.innerHTML = '<tr><td colspan="4" class="fb-empty"><span class="spinner-border spinner-border-sm"></span> Loading…</td></tr>';
  try {
    const resp = await fetch('/api/local/list', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ path: path || '', nearest: !!nearest })
    });
    const d = await resp.json();
    if (!resp.ok || d.error) throw new Error(d.error || resp.statusText);
    _fb.path = d.path;
    _fb.parent = d.parent;
    _fb.entries = d.entries || [];
    _fb.folderPick = null;
    document.getElementById('fb-path').value = d.path;
    document.getElementById('fb-filter').value = '';
    if (d.path) try { localStorage.setItem(STORAGE_FB_LAST_DIR, d.path); } catch (_) {}
    _fbRender();
    tbody.closest('.fb-list-wrap').scrollTop = 0;
  } catch (e) {
    tbody.innerHTML = `<tr><td colspan="4" class="fb-empty text-danger"><i class="bi bi-exclamation-triangle"></i> ${_fbEsc(e.message)}</td></tr>`;
  }
}

function _fbRender() {
  const isFiles = _fb.mode === 'files';
  const q = document.getElementById('fb-filter').value.trim().toLowerCase();
  const listed = _fb.entries.filter(e => e.is_dir || !isFiles || _fbAccepts(e.name));
  _fb.visible = listed.filter(e => !q || e.name.toLowerCase().includes(q));

  let html = '';
  if (_fb.parent !== null && !q) {
    html += '<tr class="fb-row" data-i="-1" title="Up one level"><td class="fb-col-check"></td>' +
      '<td class="fb-name" colspan="3"><i class="bi bi-arrow-90deg-up text-secondary"></i>..</td></tr>';
  }
  _fb.visible.forEach((e, i) => {
    const pickable = isFiles && !e.is_dir;
    const sel = pickable ? _fb.selected.has(e.path) : e.path === _fb.folderPick;
    const cls = ['fb-row', !e.is_dir && !isFiles ? 'fb-muted' : '', sel ? 'fb-selected' : ''].join(' ');
    const icon = e.is_dir ? (_fb.path ? 'bi-folder-fill fb-ic-dir' : 'bi-hdd-fill fb-ic-file') : _fbFileIcon(e.name);
    html += `<tr class="${cls}" data-i="${i}" title="${_fbEsc(e.path)}">` +
      `<td class="fb-col-check">${pickable ? `<input type="checkbox" class="form-check-input" tabindex="-1"${sel ? ' checked' : ''}>` : ''}</td>` +
      `<td class="fb-name"><i class="bi ${icon}"></i>${_fbEsc(e.name)}</td>` +
      `<td class="fb-col-date">${e.mtime ? _fbFmtDate(e.mtime) : ''}</td>` +
      `<td class="fb-col-size">${e.is_dir ? '' : formatBytes(e.size)}</td></tr>`;
  });
  if (!_fb.visible.length) {
    const msg = q ? 'Nothing matches the filter.' : (isFiles ? 'No ZIP or XML files in this folder.' : 'Empty folder.');
    html += `<tr><td colspan="4" class="fb-empty"><i class="bi bi-inbox"></i> ${msg}</td></tr>`;
  }

  const tbody = document.getElementById('fb-tbody');
  tbody.innerHTML = html;
  tbody.querySelectorAll('tr.fb-row').forEach(tr => {
    const i = +tr.dataset.i;
    const e = i < 0 ? null : _fb.visible[i];
    if (!e) {
      tr.addEventListener('click', () => _fbNavigate(_fb.parent));
      return;
    }
    if (e.is_dir) {
      tr.addEventListener('click', () => {
        if (isFiles) return;
        _fb.folderPick = e.path;
        tbody.querySelectorAll('tr.fb-selected').forEach(r => r.classList.remove('fb-selected'));
        tr.classList.add('fb-selected');
        _fbUpdateFooter();
      });
      tr.addEventListener('dblclick', () => _fbNavigate(e.path));
    } else if (isFiles) {
      tr.addEventListener('click', () => _fbToggle(e, tr));
      tr.addEventListener('dblclick', () => { _fb.selected.set(e.path, _fbPick(e)); _fbConfirm(); });
    }
  });

  const nDirs = _fb.entries.filter(e => e.is_dir).length;
  const nFiles = _fb.entries.length - nDirs;
  const hidden = _fb.entries.length - listed.length;
  let status = _fb.path
    ? `${nDirs} folder(s) · ${nFiles - hidden} ${isFiles ? 'ZIP/XML ' : ''}file(s)` + (hidden ? ` · ${hidden} other file(s) hidden` : '')
    : 'This PC';
  status += ' — double-click a folder to open it';
  document.getElementById('fb-status').textContent = status;
  _fbUpdateFooter();
}

function _fbToggle(e, tr) {
  const on = !_fb.selected.has(e.path);
  if (on) _fb.selected.set(e.path, _fbPick(e));
  else _fb.selected.delete(e.path);
  tr.classList.toggle('fb-selected', on);
  const chk = tr.querySelector('input[type="checkbox"]');
  if (chk) chk.checked = on;
  _fbUpdateFooter();
}

function _fbUpdateFooter() {
  const info = document.getElementById('fb-selection-info');
  const btn = document.getElementById('fb-btn-select');
  const label = document.getElementById('fb-btn-select-label');
  const chkAll = document.getElementById('fb-check-all');
  if (_fb.mode === 'files') {
    const files = [..._fb.selected.values()];
    const total = files.reduce((a, f) => a + (f.size || 0), 0);
    info.textContent = files.length
      ? `${files.length} file(s) selected · ${formatBytes(total)}`
      : 'Click files to select them — you can pick from several folders.';
    label.textContent = files.length ? `Use ${files.length} file(s)` : 'Use selected files';
    btn.disabled = !files.length;
    const pickable = _fb.visible.filter(e => !e.is_dir);
    const n = pickable.filter(e => _fb.selected.has(e.path)).length;
    chkAll.disabled = !pickable.length;
    chkAll.checked = pickable.length > 0 && n === pickable.length;
    chkAll.indeterminate = n > 0 && n < pickable.length;
  } else {
    const typed = document.getElementById('fb-path').value.trim();
    const target = _fb.folderPick || _fb.path || typed;
    info.textContent = target;
    label.textContent = _fb.folderPick ? 'Select highlighted folder' : 'Select this folder';
    btn.disabled = !target;
  }
}

function _fbConfirm() {
  let result;
  if (_fb.mode === 'files') {
    result = [..._fb.selected.values()];
    if (!result.length) return;
  } else {
    // A path typed (but not navigated to) wins, so not-yet-existing outputs can be chosen.
    const typed = document.getElementById('fb-path').value.trim().replace(/\\/g, '/');
    result = (typed && typed !== _fb.path) ? typed : (_fb.folderPick || _fb.path);
    if (!result) return;
  }
  const resolve = _fb.resolve;
  _fb.resolve = null;
  bootstrap.Modal.getOrCreateInstance(document.getElementById('fileBrowserModal')).hide();
  if (resolve) resolve(result);
}

/**
 * Open the file/folder browser modal.
 * @param {object} opts
 *   mode: 'folder' (default) or 'files'; exts: accepted extensions in files mode;
 *   initialPath; title; preselected: [{path, name, size}] (files mode).
 * @returns {Promise<string|Array|null>} folder path, array of files, or null if cancelled.
 */
function openFileBrowser(opts = {}) {
  return new Promise(resolve => {
    const modalEl = document.getElementById('fileBrowserModal');
    if (_fb.resolve) _fb.resolve(null);
    _fb.mode = opts.mode === 'files' ? 'files' : 'folder';
    _fb.exts = (opts.exts || []).map(e => e.toLowerCase());
    _fb.selected = new Map((opts.preselected || []).map(f => [f.path, f]));
    _fb.folderPick = null;
    _fb.entries = [];
    _fb.visible = [];
    _fb.resolve = resolve;
    modalEl.classList.toggle('fb-mode-files', _fb.mode === 'files');
    document.getElementById('fb-title').innerHTML = _fb.mode === 'files'
      ? `<i class="bi bi-file-earmark-zip"></i> ${_fbEsc(opts.title || 'Select files')}`
      : `<i class="bi bi-folder2-open"></i> ${_fbEsc(opts.title || 'Select folder')}`;
    let start = opts.initialPath || '';
    if (!start) try { start = localStorage.getItem(STORAGE_FB_LAST_DIR) || ''; } catch (_) {}
    _fbUpdateFooter();
    _fbLoadPlaces();
    _fbNavigate(start, true);
    modalEl.addEventListener('hidden.bs.modal', () => {
      if (_fb.resolve === resolve) { _fb.resolve = null; resolve(null); }
    }, { once: true });
    bootstrap.Modal.getOrCreateInstance(modalEl).show();
  });
}

/** Folder picker used by every "Browse for folder" button. Resolves '' if cancelled. */
async function browseFolder(initialDir) {
  return (await openFileBrowser({ mode: 'folder', initialPath: initialDir })) || '';
}

function initFileBrowser() {
  document.getElementById('fb-btn-up').addEventListener('click', () => {
    if (_fb.parent !== null) _fbNavigate(_fb.parent);
  });
  document.getElementById('fb-btn-refresh').addEventListener('click', () => _fbNavigate(_fb.path));
  const pathEl = document.getElementById('fb-path');
  pathEl.addEventListener('keydown', e => {
    if (e.key === 'Enter') { e.preventDefault(); _fbNavigate(pathEl.value.trim()); }
  });
  pathEl.addEventListener('input', _fbUpdateFooter);
  document.getElementById('fb-filter').addEventListener('input', _fbRender);
  document.getElementById('fb-check-all').addEventListener('change', function () {
    _fb.visible.filter(e => !e.is_dir).forEach(e => {
      if (this.checked) _fb.selected.set(e.path, _fbPick(e));
      else _fb.selected.delete(e.path);
    });
    _fbRender();
  });
  document.getElementById('fb-btn-select').addEventListener('click', _fbConfirm);
}

// ---------- Parser input files (ZIP / XML) ----------
let _parserFiles = [];

function _loadParserFiles() {
  try {
    const v = JSON.parse(localStorage.getItem(STORAGE_PARSER_FILES) || '[]');
    _parserFiles = Array.isArray(v) ? v.filter(f => f && f.path && f.name) : [];
  } catch (_) {
    _parserFiles = [];
  }
}

function _saveParserFiles() {
  try { localStorage.setItem(STORAGE_PARSER_FILES, JSON.stringify(_parserFiles)); } catch (_) {}
}

function renderParserFiles() {
  const list = document.getElementById('parser-files-list');
  const summary = document.getElementById('parser-files-summary');
  const btnClear = document.getElementById('btn-parser-clear-files');
  if (!list) return;
  list.classList.toggle('has-files', _parserFiles.length > 0);
  if (!_parserFiles.length) {
    list.innerHTML = '<div class="parser-files-empty"><i class="bi bi-file-earmark-zip"></i> ' +
      'No files selected — click here or use <strong>Browse ZIP / XML…</strong></div>';
    list.firstChild.addEventListener('click', pickParserFiles);
  } else {
    list.innerHTML = _parserFiles.map((f, i) => {
      const dir = f.path.slice(0, f.path.length - f.name.length).replace(/[\\/]$/, '');
      return `<div class="parser-file" title="${_fbEsc(f.path)}">` +
        `<i class="bi ${_fbFileIcon(f.name)}"></i>` +
        `<span class="parser-file-name">${_fbEsc(f.name)}</span>` +
        `<span class="parser-file-dir">${_fbEsc(dir)}</span>` +
        `<span class="parser-file-size">${formatBytes(f.size)}</span>` +
        `<button type="button" class="parser-file-remove" data-i="${i}" title="Remove"><i class="bi bi-x-lg"></i></button></div>`;
    }).join('');
    list.querySelectorAll('.parser-file-remove').forEach(b => b.addEventListener('click', () => {
      _parserFiles.splice(+b.dataset.i, 1);
      _saveParserFiles();
      renderParserFiles();
    }));
  }
  const total = _parserFiles.reduce((a, f) => a + (f.size || 0), 0);
  if (summary) summary.textContent = _parserFiles.length ? `${_parserFiles.length} file(s) · ${formatBytes(total)}` : 'No files selected';
  if (btnClear) btnClear.disabled = !_parserFiles.length;
}

async function pickParserFiles() {
  const last = _parserFiles.length ? _parserFiles[_parserFiles.length - 1].path.replace(/[\\/][^\\/]*$/, '') : '';
  const picked = await openFileBrowser({
    mode: 'files',
    exts: ['.zip', '.xml', '.xml.gz'],
    title: 'Select dump files (ZIP / XML)',
    initialPath: last,
    preselected: _parserFiles
  });
  if (!picked) return;
  _parserFiles = picked;
  _saveParserFiles();
  renderParserFiles();
}

/** Load saved path into input and save on change/blur so paths are remembered. */
function bindPathStorage(inputId, storageKey) {
  const el = document.getElementById(inputId);
  if (!el) return;
  try {
    const saved = localStorage.getItem(storageKey);
    if (saved) el.value = saved;
  } catch (_) {}
  el.addEventListener('change', function () {
    const v = this.value.trim();
    if (v) try { localStorage.setItem(storageKey, v); } catch (_) {}
  });
  el.addEventListener('blur', function () {
    const v = this.value.trim();
    if (v) try { localStorage.setItem(storageKey, v); } catch (_) {}
  });
}

/**
 * Build parser pipeline payload from current form state.
 * Run All passes the dump folder (overrideInputDir); the Parser card sends the picked files.
 */
function getParserPayload(overrideInputDir) {
  const outputDir = document.getElementById('parser-output-dir').value.trim();
  const customizeTxts = document.getElementById('chk-customize-txts').checked;
  const cellrefDir = (document.getElementById('parser-cellref-dir') || {}).value || 'C:/Downloader/cellref';
  const enrichedDir = (document.getElementById('parser-enriched-dir') || {}).value || 'C:/Downloader/data/enriched';
  const payload = {
    output_dir: outputDir || overrideInputDir || '',
    customize_txts: customizeTxts,
    cellref_dir: cellrefDir.trim(),
    enriched_dir: enrichedDir.trim()
  };
  if (overrideInputDir) payload.input_dir = overrideInputDir;
  else payload.input_files = _parserFiles.map(f => f.path);
  return payload;
}

/** Run full parser pipeline via streaming API. */
let _runParserAbort = null;

async function runParserPipeline() {
  const payload = getParserPayload();
  const resultEl = document.getElementById('parser-result');
  const logArea = document.getElementById('parser-log-area');
  const btnCancel = document.getElementById('btn-run-parser-cancel');
  if (!resultEl || !logArea) return;

  resultEl.style.display = 'block';
  if (!payload.input_files.length) {
    logArea.value = 'Select at least one ZIP or XML file (Browse ZIP / XML…).';
    return;
  }
  if (!payload.output_dir) {
    logArea.value = 'Set the Output Directory (parsed TXT files).';
    return;
  }

  logArea.value = 'Starting parser...\n';

  const btn = document.getElementById('btn-run-parser');
  if (btn) { btn.disabled = true; btn.innerHTML = '<i class="bi bi-hourglass-split"></i> Running...'; }
  if (btnCancel) { btnCancel.disabled = false; }

  const controller = new AbortController();
  _runParserAbort = controller;

  try {
    const response = await fetch('http://127.0.0.1:8765/api/run-parser-pipeline', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
      signal: controller.signal
    });

    if (!response.ok) {
      const errText = await response.text();
      logArea.value += '\nServer error: ' + response.status + ' ' + (errText || response.statusText);
      return;
    }

    const reader = response.body.getReader();
    const decoder = new TextDecoder();
    let buffer = '';
    while (true) {
      const { value, done } = await reader.read();
      if (done) break;
      buffer += decoder.decode(value, { stream: true });
      const lines = buffer.split(/\r?\n/);
      buffer = lines.pop() || '';
      for (const line of lines) {
        logArea.value += line + '\n';
        logArea.scrollTop = logArea.scrollHeight;
      }
    }
    if (buffer.trim()) logArea.value += buffer + '\n';
    logArea.scrollTop = logArea.scrollHeight;

  } catch (err) {
    if (err.name === 'AbortError') {
      logArea.value += '\n--- CANCELLED BY USER ---\n';
    } else {
      logArea.value += '\nError: ' + (err.message || String(err)) + '\nMake sure the server is running (START_DOWNLOADER.bat).\n';
    }
  } finally {
    _runParserAbort = null;
    if (btn) { btn.disabled = false; btn.innerHTML = '<i class="bi bi-play-fill"></i> Run Parser'; }
    if (btnCancel) { btnCancel.disabled = true; }
  }
}

function cancelParserPipeline() {
  if (_runParserAbort) {
    _runParserAbort.abort();
    _runParserAbort = null;
  }
}

/** Run dump: if server is available, POST config and stream logs; otherwise show instructions in log panel. */
async function executeDump() {
  const cmd = document.getElementById('enm-command').value.trim();
  const selected = getSelectedEnms();
  if (!cmd) {
    showEnmResult('warning', 'Generate the command first.');
    return;
  }
  if (selected.length === 0) {
    showEnmResult('warning', 'Check and fill user/password for at least one ENM.');
    return;
  }
  if (!getSitesString()) {
    showEnmResult('warning', 'Select scope (UF, city, or site list) and generate command first.');
    return;
  }

  const config = getExportConfig();
  appendLog(`[${new Date().toLocaleTimeString()}] Execute Dump: ${selected.length} ENM(s) selected.`);
  appendLog(`[${new Date().toLocaleTimeString()}] Output folder: ${config.output_dir}`);

  const apiUrl = 'http://127.0.0.1:8765/api/run-dump';
  appendLog('Calling server...');
  showEnmResult('info', 'Running dump - watch the Logs panel below.');

  try {
    const response = await fetch(apiUrl, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(config)
    });
    if (!response.ok) {
      const errText = await response.text();
      appendLog('Server error: ' + response.status + ' ' + (errText || response.statusText));
      showEnmResult('danger', 'Server error: ' + response.status);
      return;
    }
    const reader = response.body.getReader();
    const decoder = new TextDecoder();
    let buffer = '';
    while (true) {
      const { value, done } = await reader.read();
      if (done) break;
      buffer += decoder.decode(value, { stream: true });
      const lines = buffer.split(/\r?\n/);
      buffer = lines.pop() || '';
      for (const line of lines) {
        if (line.trim()) appendLog(line);
      }
    }
    if (buffer.trim()) appendLog(buffer);
    appendLog(`[${new Date().toLocaleTimeString()}] Done.`);
    showEnmResult('success', 'Dump finished. Check the Logs panel.');
  } catch (err) {
    appendLog('Error: ' + (err.message || String(err)));
    appendLog('Run START_DOWNLOADER.bat to open the tool with the server, then try Execute Dump again.');
    showEnmResult('danger', 'Could not run dump. Open the tool with START_DOWNLOADER.bat and try again.');
  }
}

// ---------- UI helpers ----------
function showEnmResult(type, message) {
  const el = document.getElementById('enm-result');
  if (!el) return;
  el.style.display = 'block';
  el.className = `alert alert-${type} mt-2`;
  el.innerHTML = message;
}

function updateStatusBar() {
  const el = document.getElementById('status-timestamp');
  if (el) {
    const now = new Date();
    el.textContent = now.toLocaleString('en-GB', {
      day: '2-digit', month: '2-digit', year: 'numeric',
      hour: '2-digit', minute: '2-digit', second: '2-digit'
    });
  }
}

// ---------- Run All (Dump + Parser) ----------
let _runAllAbort = null;

/** Returns { content: string } - the full streamed output for caller to inspect. */
async function _streamToLog(logEl, phaseEl, url, body, phaseName) {
  if (phaseEl) phaseEl.textContent = phaseName;
  logEl.value += `\n${'='.repeat(50)}\n  ${phaseName}\n${'='.repeat(50)}\n`;
  logEl.scrollTop = logEl.scrollHeight;

  const controller = new AbortController();
  _runAllAbort = controller;
  const response = await fetch(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
    signal: controller.signal
  });

  if (!response.ok) {
    const errText = await response.text();
    logEl.value += 'Server error: ' + response.status + ' ' + (errText || '') + '\n';
    throw new Error('Server error ' + response.status);
  }

  const reader = response.body.getReader();
  const decoder = new TextDecoder();
  let buffer = '';
  let fullContent = '';
  while (true) {
    const { value, done } = await reader.read();
    if (done) break;
    const chunk = decoder.decode(value, { stream: true });
    buffer += chunk;
    fullContent += chunk;
    const lines = buffer.split(/\r?\n/);
    buffer = lines.pop() || '';
    for (const line of lines) {
      logEl.value += line + '\n';
      logEl.scrollTop = logEl.scrollHeight;
    }
  }
  if (buffer.trim()) {
    logEl.value += buffer + '\n';
    fullContent += buffer + '\n';
  }
  logEl.scrollTop = logEl.scrollHeight;
  return { content: fullContent };
}

/** Returns true if Phase 1 (ENM Dump) succeeded (at least one ENM produced files). */
function _dumpPhaseSucceeded(content) {
  if (!content) return false;
  if (/Process exited with code [1-9]\d*/.test(content)) return false;
  return /OK\s+\w+:\s*Success/i.test(content);
}

async function runAll() {
  const logEl = document.getElementById('run-all-log');
  const phaseEl = document.getElementById('run-all-phase');
  const statusEl = document.getElementById('run-all-status');
  const btnClose = document.getElementById('btn-run-all-close');
  const btnCancel = document.getElementById('btn-run-all-cancel');
  const btnRunAll = document.getElementById('btn-run-all');

  // Validate dump prerequisites
  generateEnmCommand();
  const cmd = document.getElementById('enm-command').value.trim();
  const selected = getSelectedEnms();
  if (!cmd || selected.length === 0 || !getSitesString()) {
    showEnmResult('warning', 'Configure ENM connection, scope, and generate command before Run All.');
    return;
  }

  const outputDir = document.getElementById('enm-output-dir').value.trim();
  if (!outputDir) {
    showEnmResult('warning', 'Set Output Directory before running.');
    return;
  }

  // Open modal
  const modal = new bootstrap.Modal(document.getElementById('runAllModal'));
  logEl.value = `[${new Date().toLocaleTimeString()}] Run All started.\n`;
  logEl.value += `ENMs: ${selected.map(e => e.id).join(', ')}\n`;
  logEl.value += `Output: ${outputDir}\n`;
  if (btnClose) btnClose.disabled = true;
  if (btnCancel) { btnCancel.disabled = false; btnCancel.innerHTML = '<i class="bi bi-stop-fill"></i> Cancel'; }
  if (btnRunAll) btnRunAll.disabled = true;
  if (statusEl) statusEl.textContent = 'Running...';
  modal.show();

  const startTime = Date.now();

  // Cancel handler
  if (btnCancel) {
    btnCancel.onclick = () => {
      if (_runAllAbort) { _runAllAbort.abort(); _runAllAbort = null; }
      logEl.value += '\n--- CANCELLED BY USER ---\n';
      if (statusEl) statusEl.textContent = 'Cancelled.';
      if (btnClose) btnClose.disabled = false;
      if (btnCancel) { btnCancel.disabled = true; }
      if (btnRunAll) btnRunAll.disabled = false;
    };
  }

  try {
    // Phase 1: Dump
    const config = getExportConfig();
    const phase1Result = await _streamToLog(logEl, phaseEl, 'http://127.0.0.1:8765/api/run-dump', config, 'Phase 1: ENM Dump');

    if (!_dumpPhaseSucceeded(phase1Result.content)) {
      const elapsed = ((Date.now() - startTime) / 1000).toFixed(0);
      logEl.value += `\n[${new Date().toLocaleTimeString()}] Run All STOPPED: Phase 1 (ENM Dump) failed. Fix the dump error above and try again.\n`;
      if (phaseEl) phaseEl.textContent = 'Dump failed';
      if (statusEl) statusEl.textContent = `Dump failed (${elapsed}s). Parser skipped.`;
      return;
    }

    // Phase 2: Parser Pipeline (only runs if Phase 1 succeeded)
    const parserPayload = getParserPayload(outputDir);
    await _streamToLog(logEl, phaseEl, 'http://127.0.0.1:8765/api/run-parser-pipeline',
      parserPayload, 'Phase 2: XML Parser + TXT');

    const elapsed = ((Date.now() - startTime) / 1000).toFixed(0);
    logEl.value += `\n[${new Date().toLocaleTimeString()}] Run All COMPLETED in ${elapsed}s.\n`;
    if (phaseEl) phaseEl.textContent = 'Completed';
    if (statusEl) statusEl.textContent = `Completed in ${elapsed}s.`;

  } catch (err) {
    if (err.name === 'AbortError') return;
    logEl.value += '\nError: ' + (err.message || String(err)) + '\n';
    if (phaseEl) phaseEl.textContent = 'Error';
    if (statusEl) statusEl.textContent = 'Failed. Check log above.';
  } finally {
    _runAllAbort = null;
    if (btnClose) btnClose.disabled = false;
    if (btnRunAll) btnRunAll.disabled = false;
    if (btnCancel) {
      btnCancel.disabled = false;
      btnCancel.innerHTML = '<i class="bi bi-x-lg"></i> Close';
      btnCancel.onclick = () => bootstrap.Modal.getOrCreateInstance(document.getElementById('runAllModal')).hide();
    }
  }
}

// ---------- Init ----------
function init() {
  updateStatusBar();
  const statusTs = document.getElementById('status-timestamp');
  if (statusTs) setInterval(updateStatusBar, 1000);

  renderEnmRows();
  initEnmListControls();
  renderUfs();
  renderMoDefaultList();
  setAllMoCheckboxes(true);
  loadEnmProfiles();
  updateScopePanels();

  document.querySelectorAll('.scope-radio').forEach(r => {
    r.addEventListener('change', updateScopePanels);
  });
  const folderPathEl = document.getElementById('site-list-folder-path');
  if (folderPathEl) {
    bindPathStorage('site-list-folder-path', STORAGE_SITE_LIST_SAVE_DIR);
    if (!folderPathEl.value.trim()) {
      folderPathEl.value = 'C:/Downloader/cellref';
    }
    folderPathEl.addEventListener('change', () => { tryAutoLoadSiteListFromBaseDir(true); });
    folderPathEl.addEventListener('blur', () => { tryAutoLoadSiteListFromBaseDir(true); });
  }
  const btnBrowseSiteListBase = document.getElementById('btn-browse-site-list-base');
  if (btnBrowseSiteListBase && folderPathEl) {
    btnBrowseSiteListBase.addEventListener('click', async () => {
      const path = await browseFolder(folderPathEl.value);
      if (path) {
        folderPathEl.value = path;
        try { localStorage.setItem(STORAGE_SITE_LIST_SAVE_DIR, path); } catch (_) {}
        tryAutoLoadSiteListFromBaseDir(true);
      }
    });
  }
  const folderInput = document.getElementById('site-list-folder-input');
  const btnUpdateSiteList = document.getElementById('btn-update-site-list');
  if (btnUpdateSiteList && folderInput) {
    btnUpdateSiteList.addEventListener('click', async () => {
      if (siteListBusy) return;
      const existingFiles = folderInput.files;
      if (existingFiles && existingFiles.length > 0) {
        await updateSiteListFromFolder(existingFiles);
        return;
      }
      try {
        // More reliable than input.click() in some browsers/policies.
        if (typeof folderInput.showPicker === 'function') {
          await folderInput.showPicker();
        } else {
          folderInput.click();
        }
      } catch (_) {
        folderInput.click();
      }
    });
    folderInput.addEventListener('change', async function () {
      if (siteListBusy) return;
      const files = this.files;
      if (!files || !files.length) {
        showEnmResult('warning', 'No files selected. Choose one or more files to update site list.');
        return;
      }
      const inferredBase = inferBaseDirFromSelectedFiles(files);
      if (folderPathEl && inferredBase) {
        folderPathEl.value = inferredBase;
        try { localStorage.setItem(STORAGE_SITE_LIST_SAVE_DIR, inferredBase); } catch (_) {}
      }
      const names = Array.from(files).map(f => f.name).filter(Boolean);
      const preview = names.slice(0, 3).join(', ');
      const selectedLabel = names.length > 3
        ? `${names.length} files selected (${preview}, ...)`
        : `${names.length} files selected (${preview})`;
      showEnmResult('info', inferredBase
        ? `${selectedLabel}. Base dir detected: ${inferredBase}`
        : `${selectedLabel}. Base dir not auto-detected by browser; keeping current value. If needed, set Base dir using the folder button next to it.`);
      await updateSiteListFromFolder(files);
      this.value = '';
    });
  }
  const btnLoadSiteList = document.getElementById('btn-load-site-list');
  if (btnLoadSiteList) btnLoadSiteList.addEventListener('click', loadSiteListFile);
  const scopeUfSelect = document.getElementById('scope-uf-select');
  if (scopeUfSelect) scopeUfSelect.addEventListener('change', updateMunicipalityDatalist);
  const scopeMunInput = document.getElementById('scope-municipality-input');
  if (scopeMunInput) {
    scopeMunInput.addEventListener('input', updateMunicipalityDatalist);
    scopeMunInput.addEventListener('change', updateMunicipalityCount);
    scopeMunInput.addEventListener('focus', updateMunicipalityDatalist);
    scopeMunInput.addEventListener('keydown', (e) => {
      if (e.key !== 'Enter') return;
      e.preventDefault();
      const q = (scopeMunInput.value || '').trim();
      if (!q) return;
      addMunicipalitySelection(resolveCityCandidate(q));
    });
  }
  const btnAddCity = document.getElementById('btn-add-city');
  if (btnAddCity) {
    btnAddCity.addEventListener('click', () => {
      const input = document.getElementById('scope-municipality-input');
      if (!input) return;
      const q = (input.value || '').trim();
      if (!q) return;
      addMunicipalitySelection(resolveCityCandidate(q));
    });
  }
  document.getElementById('scope-tech-lte').addEventListener('change', updateMunicipalityDatalist);
  document.getElementById('scope-tech-nr').addEventListener('change', updateMunicipalityDatalist);

  // Remember all paths (load last used and save on change/blur)
  bindPathStorage('enm-output-dir', STORAGE_LAST_OUTPUT_DIR);
  bindPathStorage('parser-output-dir', STORAGE_PARSER_OUTPUT);
  bindPathStorage('parser-cellref-dir', STORAGE_PARSER_CELLREF);
  bindPathStorage('parser-enriched-dir', STORAGE_PARSER_ENRICHED);
  bindPathStorage('file-viewer-output-dir', STORAGE_FILE_VIEWER_OUTPUT);

  document.getElementById('enm-profile-select').addEventListener('change', function () {
    const name = this.value;
    if (!name) return;
    const data = loadProfilesData();
    const profile = (data.profiles || []).find(p => p.name === name);
    if (profile) applyProfileToForm(profile);
    data.last_used_profile = name;
    saveProfilesData(data);
  });

  document.getElementById('btn-save-profile').addEventListener('click', saveEnmProfile);
  document.getElementById('btn-delete-profile').addEventListener('click', deleteEnmProfile);
  document.getElementById('btn-uf-all').addEventListener('click', selectAllUfs);
  document.getElementById('btn-uf-clear').addEventListener('click', clearAllUfs);
  const btnMoSelectAll = document.getElementById('btn-mo-select-all');
  if (btnMoSelectAll) btnMoSelectAll.addEventListener('click', () => setAllMoCheckboxes(true));
  const btnMoClear = document.getElementById('btn-mo-clear');
  if (btnMoClear) btnMoClear.addEventListener('click', () => setAllMoCheckboxes(false));
  const btnMoMoB = document.getElementById('btn-mo-select-mob');
  if (btnMoMoB) btnMoMoB.addEventListener('click', selectMoB);
  const moSearchInput = document.getElementById('mo-search-input');
  if (moSearchInput) {
    moSearchInput.addEventListener('input', function () { filterMoList(this.value); });
  }
  const btnMoSearchClear = document.getElementById('btn-mo-search-clear');
  if (btnMoSearchClear) {
    btnMoSearchClear.addEventListener('click', function () {
      if (moSearchInput) { moSearchInput.value = ''; filterMoList(''); }
    });
  }
  document.getElementById('btn-add-mo').addEventListener('click', addCustomMo);
  document.getElementById('mo-custom-input').addEventListener('keydown', function (e) {
    if (e.key === 'Enter') { e.preventDefault(); addCustomMo(); }
  });
  document.getElementById('btn-generate-command').addEventListener('click', generateEnmCommand);
  document.getElementById('btn-copy-command').addEventListener('click', copyEnmCommand);

  document.getElementById('btn-execute-dump').addEventListener('click', executeDump);
  const btnClearLogs = document.getElementById('btn-clear-logs');
  if (btnClearLogs) btnClearLogs.addEventListener('click', clearLogs);

  // Folder pickers: all use the in-page file browser modal (server-side listing)
  initFileBrowser();
  const folderBrowseMap = [
    { btnId: 'btn-browse-output',            inputId: 'enm-output-dir',          storageKey: STORAGE_LAST_OUTPUT_DIR },
    { btnId: 'btn-browse-parser-output',     inputId: 'parser-output-dir',        storageKey: STORAGE_PARSER_OUTPUT },
    { btnId: 'btn-browse-parser-cellref',    inputId: 'parser-cellref-dir',       storageKey: STORAGE_PARSER_CELLREF },
    { btnId: 'btn-browse-parser-enriched',   inputId: 'parser-enriched-dir',      storageKey: STORAGE_PARSER_ENRICHED },
    { btnId: 'btn-browse-file-viewer-output',inputId: 'file-viewer-output-dir',   storageKey: STORAGE_FILE_VIEWER_OUTPUT },
  ];
  for (const { btnId, inputId, storageKey } of folderBrowseMap) {
    const btn = document.getElementById(btnId);
    const inp = document.getElementById(inputId);
    if (btn && inp) {
      btn.addEventListener('click', async () => {
        const path = await browseFolder(inp.value);
        if (path) {
          inp.value = path;
          try { localStorage.setItem(storageKey, path); } catch (_) {}
        }
      });
    }
  }

  // "Enrich Files" checkbox: show/hide enrichment options, persist state
  const chkCustomize = document.getElementById('chk-customize-txts');
  const enrichGroup = document.getElementById('enrich-options-group');
  if (chkCustomize && enrichGroup) {
    try {
      const saved = localStorage.getItem(STORAGE_CUSTOMIZE_TXTS);
      if (saved === 'true') chkCustomize.checked = true;
    } catch (_) {}
    enrichGroup.style.display = chkCustomize.checked ? 'block' : 'none';
    chkCustomize.addEventListener('change', function () {
      enrichGroup.style.display = this.checked ? 'block' : 'none';
      try { localStorage.setItem(STORAGE_CUSTOMIZE_TXTS, String(this.checked)); } catch (_) {}
    });
  }

  // Parser input files (ZIP / XML)
  _loadParserFiles();
  renderParserFiles();
  const btnParserAdd = document.getElementById('btn-parser-add-files');
  if (btnParserAdd) btnParserAdd.addEventListener('click', pickParserFiles);
  const btnParserClear = document.getElementById('btn-parser-clear-files');
  if (btnParserClear) btnParserClear.addEventListener('click', () => {
    _parserFiles = [];
    _saveParserFiles();
    renderParserFiles();
  });

  // Parser pipeline button
  const btnRunParser = document.getElementById('btn-run-parser');
  if (btnRunParser) btnRunParser.addEventListener('click', runParserPipeline);
  const btnRunParserCancel = document.getElementById('btn-run-parser-cancel');
  if (btnRunParserCancel) btnRunParserCancel.addEventListener('click', cancelParserPipeline);

  const btnExportSL = document.getElementById('btn-export-site-list');
  if (btnExportSL) btnExportSL.addEventListener('click', openExportSiteListModal);
  const btnExportSLConfirm = document.getElementById('btn-export-sl-confirm');
  if (btnExportSLConfirm) btnExportSLConfirm.addEventListener('click', confirmExportSiteList);
  const btnBrowseExportSL = document.getElementById('btn-browse-export-sl-dir');
  if (btnBrowseExportSL) {
    btnBrowseExportSL.addEventListener('click', async () => {
      const inp = document.getElementById('export-sl-dir');
      const path = await browseFolder(inp && inp.value || '');
      if (path && inp) inp.value = path;
    });
  }

  // Run All button
  const btnRunAll = document.getElementById('btn-run-all');
  if (btnRunAll) btnRunAll.addEventListener('click', runAll);

  // Auto-load site list from Base dir on startup (if sites_list.txt exists)
  tryAutoLoadSiteListFromBaseDir(true);
}

document.addEventListener('DOMContentLoaded', init);

// Shut down the backend when the browser page/tab is closed
// Signal the backend to shut down when the page unloads.
// The server uses a 3-second delayed shutdown that is automatically cancelled
// if any request arrives within that window (e.g. on page refresh).
window.addEventListener('beforeunload', function () {
  navigator.sendBeacon('http://127.0.0.1:8765/api/shutdown');
});
